<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Payment receipt {{ $payment->reference }}</title><style>body{font-family:Arial,sans-serif;margin:40px;color:#172033}header{display:flex;justify-content:space-between;border-bottom:1px solid #dbe2ea;padding-bottom:18px}h1{margin:0 0 6px}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{border-bottom:1px solid #dbe2ea;padding:10px;text-align:left}th:last-child,td:last-child{text-align:right}.total{text-align:right;margin-top:20px;font-size:18px}</style></head><body><header><div><h1>Payment Receipt</h1><strong>{{ $payment->reference }}</strong></div><div>{{ $payment->created_at?->toDateString() }}<br>{{ ucfirst(str_replace('_',' ',$payment->state)) }}</div></header><p><strong>Customer</strong><br>{{ $payment->customer?->name }}<br>{{ $payment->customer?->email }}</p><p><strong>Method:</strong> {{ $payment->method }}</p><table><thead><tr><th>Invoice</th><th>Allocated amount</th></tr></thead><tbody>@foreach($payment->allocations as $allocation)<tr><td>{{ $allocation->invoice?->number }}</td><td style="text-align:right">{{ $allocation->amount }}</td></tr>@endforeach</tbody></table><p class="total">Received: {{ $payment->amount }}</p><script>window.addEventListener('load',()=>window.print())</script></body></html>
